import { controlUnitIds, controlUnitState } from "../domain/control-units";
import { html, nothing } from "lit";
import "../components/target-range-settings-element";
import { VELAIR_FRONTEND_BUILD, VELAIR_RELEASE_VERSION } from "../build-info";
import {
  DEFAULT_EXTERNAL_CHANGE_DURATION_MINUTES,
  PORTABLE_MODEL_VERSION,
  PORTABLE_SECTIONS,
  WEEKDAYS,
} from "../constants";
import { portableImportRemovedProfileOverrides, unmatchedPreconditioningLearningEntities } from "../domain/portable";
import { entityTemperatureStep } from "../domain/climate";
import { brakingStepEquivalent } from "../domain/room-assist";
import type { VelairViewHost } from "../host-types";
import { renderInlineHelp } from "./inline-help";
import { COMMUNITY_LINKS, documentationDestination } from "../domain/documentation";
import { openDocumentationDialog, closeDocumentationDialog, restoreTriggerFocus, handleDialogClick, handleDialogKeydown, renderDocumentationHelp } from "./documentation-links";
import { renderEntityNameContext } from "./entity-name";
import type { EntityNameDisplay } from "../types";
import type { ExternalExecutionInfo, PortableSection } from "../types";

type SettingsViewHost = VelairViewHost;

export function renderSettingsView(host: SettingsViewHost, zoneIds: string[]) {
  const firstWeekday = host._firstWeekday();
  const applyOnStartup = Boolean(host._data?.settings?.apply_active_schedule_on_startup);

  return html`
    <section class="settings-view">
      ${renderTemperatureUnitSettings(host)}

      ${host._hasExternalConfig ? nothing : renderEntityNameSettings(host)}

      <label class="settings-field">
        <span class="label">${host._t("firstWeekday")}</span>
        <span class="select-wrap">
          <select
            .value=${firstWeekday}
            value=${firstWeekday}
            @change=${(event: Event) => host._updateSettingsFirstWeekday(host._inputValue(event))}
          >
            ${WEEKDAYS.map(
              (weekday: string) => html`
                <option value=${weekday} ?selected=${weekday === firstWeekday}>
                  ${host._weekdayName(weekday)}
                </option>
              `,
            )}
          </select>
        </span>
      </label>

      <section class="settings-startup">
        <ha-icon class="settings-startup-icon" icon="mdi:home-clock"></ha-icon>
        <div class="settings-startup-copy">
          <span class="section-label">${host._t("applyScheduleOnStartup")}</span>
          <p>${host._t("applyScheduleOnStartupDescription")}</p>
        </div>
        <ha-switch
          .checked=${applyOnStartup}
          ?disabled=${host._settingsSaving}
          @change=${(event: Event) =>
            host._saveSettings({
              apply_active_schedule_on_startup: Boolean((event.target as HTMLInputElement).checked),
            })}
        ></ha-switch>
      </section>

      ${renderExternalSystemsSettings(host)}

      ${renderPortabilitySettings(host)}


      <section class="settings-zone-order">
        <div class="section-heading">
          <ha-icon icon="mdi:sort"></ha-icon>
          <div>
            <span class="section-label">${host._t("zoneOrder")}</span>
            <p>${host._t("reorderZones")}</p>
          </div>
        </div>
        <velair-target-range-settings .host=${host} .data=${host._data} .zoneIds=${zoneIds}
          .renderRow=${(entityId: string, index: number, total: number, control: unknown, review: unknown, busy: boolean) => renderSettingsZoneOrderRow(host, entityId, index, total, { control, review, busy })}>
        </velair-target-range-settings>
        ${!zoneIds.length ? html`<span class="empty">${host._t("noManagedEntities")}</span>` : nothing}
      </section>

      ${renderHelpCommunitySettings(host)}

      ${renderMaintenanceSettings(host)}
    </section>
  `;
}

export function renderEntityNameSettings(host: SettingsViewHost) {
  const mode = host._data?.settings?.entity_name_display ?? "legacy";
  return html`<section class="entity-name-settings">
    <div class="settings-field">
      <div class="settings-policy-heading">
        <label class="label" for="entity-name-display">${host._t("entityNameDisplay")}</label>
        ${renderInlineHelp("entity-name-display-help", host._t("entityNameDisplay"), host._t("entityNameDisplayHelp"))}
      </div>
      <span class="select-wrap"><select id="entity-name-display" data-setting="entity_name_display" .value=${mode}
        ?disabled=${host._settingsSaving}
        @change=${(event: Event) => host._saveSettings({ entity_name_display: host._inputValue(event) as EntityNameDisplay })}>
        <option value="legacy" ?selected=${mode === "legacy"}>${host._t("entityNameDisplayLegacy")}</option>
        <option value="legacy_area" ?selected=${mode === "legacy_area"}>${host._t("entityNameDisplayLegacyArea")}</option>
        <option value="entity_context" ?selected=${mode === "entity_context"}>${host._t("entityNameDisplayEntityContext")}</option>
      </select></span>
    </div>
  </section>`;
}

export function renderHelpCommunitySettings(host: SettingsViewHost) {
  const documentation = documentationDestination("index", host.hass);
  const links = [
    { href: documentation.href, label: "documentation", description: documentation.translated ? "documentationLocalizedDescription" : "documentationDescription", icon: "mdi:book-open-page-variant" },
    { href: COMMUNITY_LINKS.issues, label: "reportIssue", description: "reportIssueDescription", icon: "mdi:bug-outline" },
    { href: COMMUNITY_LINKS.discussions, label: "questionsSuggestions", description: "questionsSuggestionsDescription", icon: "mdi:forum-outline" },
  ] as const;
  return html`<section class="settings-help">
    <div class="section-heading">
      <ha-icon icon="mdi:help-circle-outline" aria-hidden="true"></ha-icon>
      <div>
        <span class="section-label">${host._t("helpCommunity")}</span>
        <p>${host._t("helpCommunityDescription")}</p>
      </div>
    </div>
    <div class="settings-help-links">
      ${links.map((link) => html`<a class="documentation-link help-community-link" href=${link.href}
        target="_blank" rel="noopener noreferrer">
        <ha-icon icon=${link.icon} aria-hidden="true"></ha-icon>
        <span><strong>${host._t(link.label)}</strong><small>${host._t(link.description)}</small></span>
        <ha-icon icon="mdi:open-in-new" aria-hidden="true"></ha-icon>
      </a>`)}
    </div>
  </section>`;
}

export function renderExternalSystemsSettings(host: SettingsViewHost) {
  const external = host._data?.external_execution;
  if (!external || (!external.systems.length && !Object.keys(external.zones).length)) {
    return nothing;
  }
  const eligibleProviders = new Map<string, Array<{ provider: string; name: string }>>();
  for (const system of external.systems) {
    for (const entityId of system.entities) {
      const providers = eligibleProviders.get(entityId) ?? [];
      providers.push({ provider: system.provider, name: system.name });
      eligibleProviders.set(entityId, providers);
    }
  }
  const entityIds = Array.from(new Set([
    ...eligibleProviders.keys(),
    ...Object.keys(external.zones),
  ]));
  const systemsByProvider = new Map(external.systems.map((system) => [system.provider, system]));
  const selectedSystems = selectedExternalSystems(external);
  return html`
    <section class="settings-startup external-systems-settings">
      <ha-icon class="settings-startup-icon" icon="mdi:calendar-export"></ha-icon>
      <div class="settings-startup-copy">
        <div class="documentation-heading">
          <span class="section-label">${host._t("externalSystems")}</span>
          ${renderDocumentationHelp(host, "externalSystems")}
        </div>
        <p>${host._t("externalSystemsDescription")}</p>
        <div class="settings-zone-list">
          ${entityIds.map((entityId) => {
            const configured = external.zones[entityId];
            const providers = eligibleProviders.get(entityId) ?? [];
            return html`
              <label class="settings-field external-system-zone">
                <span class="external-system-zone-identity">
                  <strong>${host._friendlyEntityName(entityId)}</strong>${renderEntityNameContext(host._data, host.hass, entityId)}
                </span>
                <span class="select-wrap external-system-zone-select">
                  <select
                    ?disabled=${host._settingsSaving}
                    @change=${async (event: Event) => {
                      const select = event.currentTarget as HTMLSelectElement;
                      const provider = select.value;
                      const selected = await host._setZoneExecution(
                        entityId,
                        provider || undefined,
                      );
                      if (!selected) {
                        select.value = host._data?.external_execution?.zones[entityId]?.provider ?? "";
                      }
                    }}
                  >
                    <option value="" ?selected=${!configured}>${host._t("externalExecutionVelair")}</option>
                    ${providers.map((provider) => html`
                      <option
                        value=${provider.provider}
                        ?selected=${configured?.provider === provider.provider}
                      >${provider.name}${configured?.provider === provider.provider && !configured.available
                        ? ` (${host._t("externalProviderUnavailable")})`
                        : ""}</option>
                    `)}
                    ${configured && !providers.some((item) => item.provider === configured.provider)
                      ? html`<option value=${configured.provider} selected>${systemsByProvider.get(configured.provider)?.name
                        ?? configured.provider} (${host._t("externalProviderUnavailable")})</option>`
                      : nothing}
                  </select>
                </span>
              </label>
            `;
          })}
        </div>
        ${selectedSystems.length ? html`
          <div class="external-controllers-in-use">
            <strong>${host._t("externalControllersInUse")}</strong>
            ${selectedSystems.map((system) => html`
              <details class="external-controller-conditions">
                <summary>
                  <ha-icon icon="mdi:server-network"></ha-icon>
                  <strong>${system.name}</strong>
                  <ha-icon class="external-controller-expand-icon" icon="mdi:chevron-down"></ha-icon>
                </summary>
                <div class="external-controller-conditions-body">
                ${system.capabilities ? html`
                  <ul>
                    ${system.capabilities.supports_profile_schedules
                      ? html`<li>${host._t("externalConditionProfilesSupported")}</li>` : nothing}
                    <li>${host._t("externalConditionHvacModes", {
                      modes: formatExternalCapabilities(host, "hvac", system.capabilities.supported_hvac_modes),
                    })}</li>
                    <li>${host._t("externalConditionTargetTypes", {
                      types: formatExternalCapabilities(host, "target", system.capabilities.supported_target_types),
                    })}</li>
                    <li>${host._t("externalConditionActions", {
                      actions: formatExternalCapabilities(host, "action", system.capabilities.supported_actions),
                    })}</li>
                    ${system.capabilities.supported_actions.includes("turn_off")
                      ? nothing : html`<li>${host._t("externalConditionTurnOffUnsupported")}</li>`}
                    <li>${system.capabilities.supported_option_fields.length
                      ? host._t("externalConditionOptionFields", {
                          fields: system.capabilities.supported_option_fields.join(", "),
                        })
                      : host._t("externalConditionOptionsUnsupported")}</li>
                    <li>${host._t("externalConditionMaxChanges", {
                      count: system.capabilities.max_switchpoints_per_day,
                    })}</li>
                    <li>${host._t("externalConditionTimeGrid", {
                      minutes: system.capabilities.time_step_minutes,
                    })}</li>
                    ${system.capabilities.implicit_midnight_change_counts_toward_limit
                      ? html`<li>${host._t("externalConditionMidnightContinuityCounts")}</li>`
                      : nothing}
                  </ul>
                ` : html`<small>${host._t("externalConditionsUnavailable")}</small>`}
                </div>
              </details>
            `)}
          </div>
        ` : nothing}
      </div>
    </section>
  `;
}

function formatExternalCapabilities(
  host: SettingsViewHost,
  kind: "action" | "hvac" | "target",
  values: string[],
): string {
  return values.map((value) => {
    const key = `externalCapability_${kind}_${value}`;
    const translated = host._t(key as never);
    return translated === key ? value.replaceAll("_", " ") : translated;
  }).join(", ");
}

export function selectedExternalSystems(external: ExternalExecutionInfo) {
  const systems = new Map(external.systems.map((system) => [system.provider, system]));
  return Array.from(new Set(Object.values(external.zones).map((zone) => zone.provider)))
    .map((provider) => {
      const system = systems.get(provider);
      return system ?? { provider, name: provider, capabilities: null };
    });
}

export function renderTemperatureUnitSettings(host: SettingsViewHost) {
  const migrationRequired = Boolean(host._data?.temperature_migration?.required);
  const unit = host._data?.home_assistant_temperature_unit ?? host._temperatureUnit();
  const migration = host._data?.temperature_migration;
  const legacyResetRequired = migration?.reason === "legacy_celsius_upgrade_reset_required";
  const sourceUnit = migration?.source_unit;
  const targetUnit = migration?.target_unit ?? unit;
  return html`
    <section class=${migrationRequired ? "settings-temperature migration-required" : "settings-temperature"}>
      <ha-icon class="settings-startup-icon" icon="mdi:thermometer-lines"></ha-icon>
      <div class="settings-temperature-copy">
        <span class="section-label">${host._t("temperatureUnit")}</span>
        <p>${host._t("temperatureUnitManagedByHomeAssistant")}</p>
        ${migrationRequired
          ? html`
              <div class="temperature-migration-action" role="alert">
                <strong>${legacyResetRequired
                  ? host._t("temperatureLegacyResetQuestion", { target: targetUnit })
                  : host._t("temperatureMigrationQuestion", { source: sourceUnit ?? "?", target: targetUnit })}</strong>
                <p>${legacyResetRequired
                  ? host._t("temperatureLegacyResetExplanation", { target: targetUnit })
                  : host._t("temperatureMigrationExplanation", { source: sourceUnit ?? "?", target: targetUnit })}</p>
                <div class="temperature-migration-buttons">
                  ${legacyResetRequired
                    ? html`
                      <button
                        class="command-button danger"
                        type="button"
                        ?disabled=${host._maintenanceAction === "reset"}
                        @click=${() => host._resetVelairData()}
                      >
                        ${host._maintenanceAction === "reset"
                          ? host._t("resetting")
                          : host._t("resetVelair")}
                      </button>
                    `
                    : sourceUnit
                    ? html`
                      <button
                        class="command-button primary"
                        type="button"
                        ?disabled=${Boolean(host._temperatureMigrationAction)}
                        @click=${() => host._resolveTemperatureMigration(sourceUnit)}
                      >
                        ${host._temperatureMigrationAction === sourceUnit
                          ? host._t("applying")
                          : host._t("temperatureMigrationUse", { source: sourceUnit, target: targetUnit })}
                      </button>
                    `
                    : nothing}
                </div>
              </div>
            `
          : nothing}
      </div>
      <strong class="settings-temperature-value">${unit}</strong>
    </section>
  `;
}

export function renderMaintenanceSettings(host: SettingsViewHost) {
  const versions = host._data?.versions ?? {};
  const portableVersion = versions.portable_model ?? PORTABLE_MODEL_VERSION;
  const storageVersion = versions.storage ?? 1;
  const modelVersion = versions.model ?? 1;
  const integrationVersion = VELAIR_RELEASE_VERSION || versions.integration || "-";
  const resetting = host._maintenanceAction === "reset";
  const migrationRequired = Boolean(host._data?.temperature_migration?.required);
  const legacyResetRequired = host._data?.temperature_migration?.reason === "legacy_celsius_upgrade_reset_required";

  return html`
    <section class="settings-maintenance">
      <div class="settings-portability-heading">
        <ha-icon class="settings-startup-icon" icon="mdi:wrench-clock"></ha-icon>
        <div>
          <span class="section-label">${host._t("maintenance")}</span>
          <p>${host._t("maintenanceDescription")}</p>
        </div>
      </div>

      ${host.hass?.user?.is_admin ? renderSensorEntityIdsReview(host) : nothing}
      <div class="maintenance-grid">
        ${renderMaintenanceItem(host._t("frontendBuild"), VELAIR_FRONTEND_BUILD)}
        ${renderMaintenanceItem(host._t("portableFormatVersion"), `v${portableVersion}`)}
        ${renderMaintenanceItem(host._t("internalStorageVersion"), `v${storageVersion} / v${modelVersion}`)}
        ${renderMaintenanceItem(host._t("integrationVersion"), integrationVersion)}
      </div>
    </section>

    <section class="settings-reset">
      <ha-icon class="settings-reset-icon" icon="mdi:delete-alert-outline"></ha-icon>
      <div class="settings-reset-copy">
        <span class="section-label">${host._t("resetVelair")}</span>
        <p>${host._t("resetVelairDescription")}</p>
      </div>
      <button
        class="command-button danger"
        type="button"
        ?disabled=${resetting || (migrationRequired && !legacyResetRequired)}
        @click=${() => host._resetVelairData()}
      >
        <ha-icon icon="mdi:restore"></ha-icon>
        <span>${resetting ? host._t("resetting") : host._t("resetVelair")}</span>
      </button>
    </section>
  `;
}

export function renderMaintenanceItem(label: string, value: string | number) {
  return html`
    <div class="maintenance-item">
      <span class="label">${label}</span>
      <strong>${value}</strong>
    </div>
  `;
}

export function renderPortabilitySettings(host: SettingsViewHost) {
  const importSections = host._importAvailableSections();
  const canExport = host._exportSections.size > 0
    && !host._portabilityAction;
  const canImport = Boolean(host._importPayload) && host._importSections.size > 0 && !host._portabilityAction;
  const exportItems = new Map(host._portableExportSummaryItems().map((item) => [item.section, item]));
  const importItems = new Map(host._portableImportSummaryItems().map((item) => [item.section, item]));
  const unmatchedLearningEntities = host._importSections.has("preconditioning_learning")
    ? unmatchedPreconditioningLearningEntities(
        host._importPayload,
        [...controlUnitIds(host._data), ...(host._importSections.has("room_groups") ? Object.keys(host._importPayload?.sections?.room_groups ?? {}) : [])],
      )
    : [];
  const legacyTemperatureUnit = Boolean(
    host._importPayload && host._importPayload.temperature_unit === undefined,
  );

  return html`
    <section class="settings-portability">
      <div class="settings-portability-heading">
        <ha-icon class="settings-startup-icon" icon="mdi:file-sync-outline"></ha-icon>
        <div>
          <span class="section-label">${host._t("portability")}</span>
          <p>${host._t("portabilityDescription")}</p>
        </div>
      </div>

      <div class="portability-grid">
        <div class="portability-card portability-export-card">
          <div class="portability-options">
            ${PORTABLE_SECTIONS.map((section) =>
              renderPortableSectionOption(
                host,
                "export",
                section,
                host._exportSections.has(section),
                false,
                exportItems.get(section),
              ),
            )}
          </div>
          <button
            class="command-button primary"
            type="button"
            ?disabled=${!canExport}
            @click=${() => host._exportPortableData()}
          >
            <ha-icon icon="mdi:download"></ha-icon>
            <span>${host._portabilityAction === "export" ? host._t("saving") : host._t("exportData")}</span>
          </button>
        </div>

        <div class="portability-card">
          <label class="portable-file-field">
            <span class="label">${host._t("importFile")}</span>
            <span class="portable-file-control">
              <input
                type="file"
                accept="application/json,.json"
                ?disabled=${Boolean(host._portabilityAction)}
                @change=${(event: Event) => host._handlePortableImportFile(event)}
              />
              <span class="portable-file-button">${host._t("chooseFile")}</span>
              <span class="portable-file-name">${host._importFileName || host._t("noFileSelected")}</span>
            </span>
          </label>
          ${host._importFileName
            ? html`<span class="empty">${host._t("portabilityFileReady", { file: host._importFileName })}</span>`
            : nothing}
          ${host._importPayload
            ? html`
                <div class="portable-warning" role="alert">
                  <ha-icon icon="mdi:alert-outline"></ha-icon>
                  <span>${host._t("importOverwriteWarning")}</span>
                </div>
              `
            : nothing}
          ${portableImportRemovedProfileOverrides(host._data, host._importPayload, host._importSections).length
            ? html`<div class="portable-warning" role="alert"><ha-icon icon="mdi:layers-remove"></ha-icon><span>
                ${host._t("profileImportOverridesWarning")}
                ${portableImportRemovedProfileOverrides(host._data, host._importPayload, host._importSections).join(", ")}
              </span></div>` : nothing}
          ${legacyTemperatureUnit
            ? html`
                <div class="portable-warning" role="status">
                  <ha-icon icon="mdi:thermometer-alert"></ha-icon>
                  <span>${host._t("legacyImportTemperatureUnit", {
                    target: host._data?.home_assistant_temperature_unit
                      ?? host._temperatureUnit(),
                  })}</span>
                </div>
              `
            : nothing}
          ${unmatchedLearningEntities.length
            ? html`
                <div class="portable-warning" role="alert">
                  <ha-icon icon="mdi:thermometer-alert"></ha-icon>
                  <span>
                    ${host._t("preconditioningImportSkipped", {
                      count: unmatchedLearningEntities.length,
                      entities: unmatchedLearningEntities.join(", "),
                    })}
                  </span>
                </div>
              `
            : nothing}
          <div class="portability-options">
            ${importSections.length
              ? importSections.map((section: PortableSection) =>
                  renderPortableSectionOption(
                    host,
                    "import",
                    section,
                    host._importSections.has(section),
                    false,
                    importItems.get(section),
                  ),
                )
              : html`<span class="empty">${host._t("noImportSections")}</span>`}
          </div>
          <button
            class="command-button success"
            type="button"
            ?disabled=${!canImport}
            @click=${() => host._importPortableData()}
          >
            <ha-icon icon="mdi:upload"></ha-icon>
            <span>${host._portabilityAction === "import" ? host._t("applying") : host._t("importData")}</span>
          </button>
        </div>
      </div>
    </section>
  `;
}

export function renderPortableSectionOption(
  host: SettingsViewHost,
  target: "export" | "import",
  section: PortableSection,
  checked: boolean,
  disabled: boolean,
  item?: { label: string; title: string; value: string | number },
) {
  return html`
    <label class="portable-option" title=${item?.title ?? host._portableSectionLabel(section)}>
      <input
        type="checkbox"
        .checked=${checked}
        ?disabled=${disabled || Boolean(host._portabilityAction)}
        @change=${(event: Event) =>
          host._togglePortableSection(target, section, Boolean((event.currentTarget as HTMLInputElement).checked))}
      />
      ${item && typeof item.value === "number"
        ? html`<strong>${item.value}</strong>`
        : nothing}
      <span>${item?.label ?? host._portableSectionLabel(section)}</span>
    </label>
  `;
}

export function renderSettingsZoneOrderRow(
  host: SettingsViewHost,
  entityId: string,
  index: number,
  total: number,
  options: { control?: unknown; review?: unknown; busy?: boolean } = {},
) {
  const disabled = options.busy || host._settingsSaving;
  return html`
    <div
      class="settings-zone-row" data-entity-id=${entityId}
      @dragover=${(event: DragEvent) => { if (!disabled) host._handleSettingsZoneDragOver(event); }}
      @drop=${(event: DragEvent) => { if (!disabled) host._handleSettingsZoneDrop(entityId, event); }}
      @dragend=${host._handleSettingsZoneDragEnd}
    >
      <header class="settings-zone-header">
      <button
        class="settings-drag-handle"
        type="button"
        title=${host._t("reorderZones")}
        aria-label=${host._t("reorderZones")}
        draggable=${disabled ? "false" : "true"}
        ?disabled=${disabled}
        @dragstart=${(event: DragEvent) => { if (!disabled) host._handleSettingsZoneDragStart(entityId, event); }}
        @dragend=${host._handleSettingsZoneDragEnd}
      >
        <ha-icon icon="mdi:drag"></ha-icon>
      </button>
        <div class="settings-zone-identity">
          <div class="settings-zone-title">
            <strong title=${host._friendlyEntityName(entityId)}>${host._friendlyEntityName(entityId)}</strong>${renderEntityNameContext(host._data, host.hass, entityId)}
          </div>
          <span>${entityId}</span>
        </div>
      <div class="settings-row-actions">
        <button
          class="icon-button"
          type="button"
          title=${host._t("moveUp")}
          ?disabled=${disabled || index === 0}
          @click=${() => host._moveSettingsZone(entityId, -1)}
        >
          <ha-icon icon="mdi:chevron-up"></ha-icon>
        </button>
        <button
          class="icon-button"
          type="button"
          title=${host._t("moveDown")}
          ?disabled=${disabled || index === total - 1}
          @click=${() => host._moveSettingsZone(entityId, 1)}
        >
          <ha-icon icon="mdi:chevron-down"></ha-icon>
        </button>
      </div>
      </header>
      <div class="settings-zone-configuration">
        ${renderSettingsExternalChangePolicy(host, entityId, Boolean(disabled))}
        ${renderSettingsTargetTempStep(host, entityId, Boolean(disabled))}
        ${renderSettingsHighBrakingSteps(host, entityId, Boolean(disabled))}
        ${options.control ?? nothing}
      </div>
      ${options.review ?? nothing}
    </div>
  `;
}

export function renderSettingsHighBrakingSteps(host: SettingsViewHost, entityId: string, disabled = host._settingsSaving) {
  const zone = host._data?.zones[entityId];
  if (zone?.execution?.type === "external") return nothing;
  const steps = zone?.preconditioning?.room_sensor_assist_high_braking_steps ?? 2;
  const step = host._entityTemperatureStep(entityId);
  const equivalent = brakingStepEquivalent(steps, step, host._temperatureUnit(entityId));
  const key = entityId.replace(/[^a-zA-Z0-9_-]/g, "-");
  const inputId = `high-braking-steps-${key}`;
  const descriptionId = `${inputId}-description`;
  return html`
    <div class="settings-target-temp-step settings-high-braking-steps">
      <div class="settings-policy-heading">
        <label class="label" for=${inputId}>${host._t("highBrakingSteps")}</label>
        ${renderInlineHelp(`${inputId}-help`, host._t("highBrakingSteps"), host._t("highBrakingStepsHelp"))}
      </div>
      <div class="settings-high-braking-content">
        <span class="settings-target-temp-step-control">
          <input id=${inputId} type="number" inputmode="numeric" min="2" max="10" step="1" required
            aria-describedby=${descriptionId} .value=${String(steps)} ?disabled=${disabled}
            @change=${(event: Event) => {
              const input = event.currentTarget as HTMLInputElement;
              const value = Number(input.value);
              if (!input.reportValidity() || !Number.isInteger(value) || value < 2 || value > 10) {
                input.value = String(steps);
                return;
              }
              input.value = String(steps);
              if (value !== steps) void host._saveZonePreconditioning(entityId, { room_sensor_assist_high_braking_steps: value });
            }} />
          <span>${host._t("highBrakingStepsUnit")}</span>
        </span>
        <small id=${descriptionId} class="settings-high-braking-equivalent">${equivalent !== undefined
          ? host._t("highBrakingStepsEquivalent", { value: equivalent })
          : host._t("highBrakingStepsUnknown")}</small>
      </div>
    </div>`;
}

export function renderSettingsTargetTempStep(host: SettingsViewHost, entityId: string, disabled = host._settingsSaving) {
  const publishedStep = entityTemperatureStep(controlUnitState(host._data, host.hass, entityId));
  if (publishedStep !== undefined) return nothing;
  const zone = host._data?.zones?.[entityId];
  const configuredStep = zone?.last_reported_target_temp_step
    ?? zone?.target_temp_step_override
    ?? 1;
  const [minimum, maximum] = host._entityTemperatureLimits(entityId);
  const maximumStep = Math.max(0.001, maximum - minimum);
  const key = entityId.replace(/[^a-z0-9_-]/gi, "-");
  const labelId = `target-temp-step-label-${key}`;
  const helpId = `target-temp-step-help-${key}`;
  return html`
    <div class="settings-target-temp-step">
      <div class="settings-policy-heading">
        <span class="label" id=${labelId}>${host._t("targetTempStepFallback")}</span>
        ${renderInlineHelp(
          helpId,
          host._t("targetTempStepFallbackInfoAction"),
          host._t("targetTempStepFallbackDescription"),
        )}
      </div>
      <label class="settings-target-temp-step-control">
        <input
          type="number"
          inputmode="decimal"
          min="0.001"
          max=${String(maximumStep)}
          step="any"
          required
          aria-labelledby=${labelId}
          .value=${String(configuredStep)}
          ?disabled=${disabled}
          @change=${(event: Event) => {
            const input = event.currentTarget as HTMLInputElement;
            const value = Number(input.value);
            if (!input.reportValidity() || !Number.isFinite(value) || value < 0.001) {
              input.value = String(configuredStep);
              return;
            }
            void host._saveZoneTargetTempStep(entityId, value);
          }}
        />
        <span>${host._temperatureUnit(entityId)}</span>
      </label>
    </div>
  `;
}

export function renderSettingsExternalChangePolicy(host: SettingsViewHost, entityId: string, disabled = host._settingsSaving) {
  if (host._data?.zones[entityId]?.execution?.type === "external") {
    return html`<small>${host._t("externalActionsInactive")}</small>`;
  }
  const policy = host._data?.zones[entityId]?.external_change_policy ?? {
    action: "keep_automatic" as const,
    duration_minutes: DEFAULT_EXTERNAL_CHANGE_DURATION_MINUTES,
  };
  const key = entityId.replace(/[^a-z0-9_-]/gi, "-");
  const labelId = `external-adjustment-label-${key}`;
  return html`
    <div class="settings-external-policy">
      <div class="settings-policy-heading">
        <span class="label" id=${labelId}>${host._t("externalChangePolicy")}</span>
        ${renderDocumentationHelp(host, "manualControl", {
          title: "externalChangePolicy",
          summary: "externalChangePolicyDescription",
        })}
      </div>
      <div class="settings-policy-controls">
        <span class="select-wrap">
          <select
            aria-labelledby=${labelId}
            .value=${policy.action}
            ?disabled=${disabled}
            @change=${(event: Event) => host._saveExternalChangePolicy(entityId, {
              ...policy,
              action: (event.target as HTMLSelectElement).value as typeof policy.action,
            })}
          >
            <option value="keep_automatic" .selected=${policy.action === "keep_automatic"}>${host._t("externalChangeKeepAutomatic")}</option>
            <option value="until_next_block" .selected=${policy.action === "until_next_block"}>${host._t("externalChangeUntilNextBlock")}</option>
            <option value="for_duration" .selected=${policy.action === "for_duration"}>${host._t("externalChangeForDuration")}</option>
            <option value="until_resumed" .selected=${policy.action === "until_resumed"}>${host._t("externalChangeUntilResumed")}</option>
          </select>
        </span>
        ${policy.action === "for_duration" ? html`
          <label class="settings-policy-duration">
            <input
              type="number"
              min="1"
              max="10080"
              aria-label=${host._t("durationMinutes")}
              .value=${String(policy.duration_minutes ?? DEFAULT_EXTERNAL_CHANGE_DURATION_MINUTES)}
              ?disabled=${disabled}
              @change=${(event: Event) => host._saveExternalChangePolicy(entityId, {
                ...policy,
                duration_minutes: Math.max(
                  1,
                  Math.min(
                    10080,
                    Number((event.target as HTMLInputElement).value)
                      || DEFAULT_EXTERNAL_CHANGE_DURATION_MINUTES,
                  ),
                ),
              })}
            />
            <span>${host._t("minutesShort")}</span>
          </label>
        ` : nothing}
      </div>
    </div>
  `;
}

function renderSensorEntityIdChange(currentId: string, proposedId: string) {
  return html`<span class="sensor-ids-map"><code>${currentId}</code>
    <ha-icon class="sensor-ids-arrow" icon="mdi:arrow-right" aria-hidden="true"></ha-icon>
    <code>${proposedId}</code></span>`;
}

export function renderSensorEntityIdsReview(host: SettingsViewHost) {
  const busy = Boolean(host._sensorIdsAction);
  const result = host._sensorIdsResult;
  return html`<div class="sensor-ids-maintenance-action">
    <button class="documentation-link help-community-link sensor-ids-review-trigger" type="button" data-dialog-trigger aria-haspopup="dialog"
      aria-label=${host._t("sensorIdsReview")} aria-describedby="sensor-ids-maintenance-description"
      @click=${(event: Event) => { openDocumentationDialog(event); void host._previewSensorEntityIds(); }}>
      <ha-icon icon="mdi:identifier" aria-hidden="true"></ha-icon>
      <span><strong>${host._t("sensorIdsReview")}</strong>
        <small id="sensor-ids-maintenance-description">${host._t("sensorIdsDescription")}</small></span>
    </button>
    <dialog class="documentation-dialog sensor-ids-dialog" aria-labelledby="sensor-ids-title" aria-describedby="sensor-ids-warning"
      aria-busy=${String(busy)} @click=${(event: MouseEvent) => { if (!busy) handleDialogClick(event); }}
      @keydown=${handleDialogKeydown} @cancel=${(event: Event) => { if (busy) event.preventDefault(); }} @close=${restoreTriggerFocus}>
      <header class="documentation-dialog-header">
        <h2 id="sensor-ids-title">${host._t("sensorIdsReview")}</h2>
        <button class="documentation-close" type="button" autofocus aria-label=${host._t("close")} ?disabled=${busy}
          @click=${(event: Event) => { if (!busy) closeDocumentationDialog(event); }}><ha-icon icon="mdi:close" aria-hidden="true"></ha-icon></button>
      </header>
      <div class="sensor-ids-dialog-body">
        <p id="sensor-ids-warning">${host._t("sensorIdsWarning")}</p>
        ${host._sensorIdsAction === "preview" ? html`<p role="status">${host._t("loading")}</p>` : nothing}
        ${host._sensorIdsError ? html`<p role="alert">${host._sensorIdsError}</p>` : nothing}
        ${result ? html`<section role=${result.status === "applied" ? "status" : "alert"}>
          <p>${host._t(result.status === "applied" ? "sensorIdsApplied" : result.status === "rolled_back" ? "sensorIdsRolledBack" : "sensorIdsRecoveryRequired")}</p>
          ${result.renamed.length ? html`<p>${host._t("sensorIdsRemainingRenamed")}</p><ul>${result.renamed.map(row => html`<li>${renderSensorEntityIdChange(row.old_entity_id, row.new_entity_id)}</li>`)}</ul>` : nothing}
          ${result.failed.map(row => html`<p><code>${row.entity_id}</code>: ${row.message}</p>`)}
        </section>` : nothing}
        ${host._sensorIdsPreview ? html`<div class="sensor-ids-rows">
          ${!host._sensorIdsPreview.rows.length ? html`<p>${host._t("sensorIdsEmpty")}</p>` : nothing}
          ${host._sensorIdsPreview.rows.map(row => html`<label class="sensor-ids-row">
            <input type="checkbox" .checked=${host._sensorIdsSelected.has(row.entity_id)} ?disabled=${busy || row.status !== "ready"}
              @change=${(event: Event) => host._toggleSensorEntityId(row.entity_id, (event.currentTarget as HTMLInputElement).checked)} />
            <span><strong>${row.name}</strong><small>${host._friendlyEntityName(row.climate_entity_id)} · ${row.climate_entity_id}</small>
              ${renderSensorEntityIdChange(row.entity_id, row.proposed_entity_id)}
              ${row.status !== "ready" ? html`<small>${host._t(row.status === "conflict" ? "sensorIdsConflict" : "sensorIdsUnchanged")}</small>` : nothing}
            </span>
          </label>`)}
        </div>` : nothing}
      </div>
      <footer class="documentation-dialog-footer">
        <button class="command-button compact" type="button" ?disabled=${busy} @click=${() => host._previewSensorEntityIds()}>${host._t("sensorIdsRefresh")}</button>
        <button class="command-button primary compact" type="button" ?disabled=${busy || !host._sensorIdsPreview || !host._sensorIdsSelected.size}
          @click=${() => host._applySensorEntityIds()}>${host._t(host._sensorIdsAction === "apply" ? "applying" : "sensorIdsApply")}</button>
      </footer>
    </dialog>
  </div>`;
}
